#!/usr/bin/env bash
#
# 从上游原文 .github/scripts/.upstream/docker-compose.yml 生成项目根的 docker-compose.yml。
#
# 上游的根文件用 `include:` 汇总约 150 个服务，每项是一个 `<dir>/compose.yml`，
# 并在 `volumes:` 段声明它们的命名卷。本脚本做两件事：
#
#   1. 裁剪：只保留 SYNC_DIRS（见 .sync-config.sh）里的 include 条目和命名卷。
#      `networks:` 段原样保留。
#
#   2. 接线：如果 <service>/compose.override.yml 存在，就把该服务的
#        path: <service>/compose.yml
#      改写成
#        path:
#          - <service>/compose.yml            # 上游原文
#          - <service>/compose.override.yml   # 本项目定制
#      Compose 遇到 path 列表时会把后面的合并到前面的之上（详见
#      php-fpm/compose.override.yml 的注释）。
#
#   3. 兜底：保留下来的上游 compose.yml 会引用一些属于「我们不跑的服务」的
#      变量（如 nginx/compose.yml 里的 ${VARNISH_BACKEND_PORT}）。上游把它们
#      放在根 .env.example，而本项目的 .env.example 是按服务裁剪过的，于是
#      `docker compose config` 会刷屏 "variable is not set" 告警。
#      解决办法：把上游原文 .env.upstream（见 .sync-config.sh 的 SYNC_FILES）
#      挂到每个 include 条目的 env_file 上。它只用于插值，不会注入到容器的
#      environment 里。
#      优先级：shell 环境变量 > 根 .env > env_file 列表（列表内后者覆盖前者），
#      所以你在 .env 里写的值永远说了算。上游这份根 .env.example 只放全局变量，
#      与 <service>/defaults.env 的变量集合无交集，两者顺序不影响结果。
#
# 也就是说：加一个服务的定制，只要在它目录里放一个 compose.override.yml
# 再跑本脚本，不用手改 include 列表。
#
# 依赖：yq v4（mikefarah/yq）。使用方法：.github/scripts/generate-docker-compose.sh

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" >/dev/null 2>&1 && pwd)"
ROOT_DIR="$(cd "${SCRIPT_DIR}/../.." && pwd)"
# shellcheck source=.github/scripts/.sync-config.sh
source "${SCRIPT_DIR}/.sync-config.sh"

SRC_FILE="${SCRIPT_DIR}/.upstream/docker-compose.yml"
DEST_FILE="${ROOT_DIR}/docker-compose.yml"
OVERRIDE_BASENAME="compose.override.yml"
UPSTREAM_ENV_REL=".env.upstream"   # 相对 project_directory（即根目录）

if ! command -v yq >/dev/null 2>&1; then
  echo "!! yq (mikefarah/yq v4) is required but not found in PATH" >&2
  exit 1
fi

if [[ ! -f "${SRC_FILE}" ]]; then
  echo "!! Skipping: ${SRC_FILE} not found (run .github/scripts/sync-upstream.sh first)" >&2
  exit 0
fi

# 带 <service>/compose.override.yml 的服务名清单（所在目录名即服务名）。
shopt -s nullglob
override_services=()
for f in "${ROOT_DIR}"/*/"${OVERRIDE_BASENAME}"; do
  service_dir="${f%/*}"
  override_services+=( "${service_dir##*/}" )
done
shopt -u nullglob

echo "==> Generating ${DEST_FILE#"${ROOT_DIR}"/} from ${SRC_FILE#"${ROOT_DIR}"/}"
echo "    keeping services : ${SYNC_DIRS[*]}"
echo "    wiring overrides : ${override_services[*]:-(none)}"
echo "    env fallback     : ${UPSTREAM_ENV_REL}"

# yq 的 load() 只能从文件读取，把两份清单写成 YAML 列表文件供表达式引用。
names_file="$(mktemp)"
ovr_file="$(mktemp)"
trap 'rm -f "${names_file}" "${ovr_file}"' EXIT
printf -- '- %s\n' "${SYNC_DIRS[@]}" > "${names_file}"
: > "${ovr_file}"
(( ${#override_services[@]} )) && printf -- '- %s\n' "${override_services[@]}" > "${ovr_file}"

# 文件头注释：说明本文件是自动生成的，不要手工编辑。
cat > "${DEST_FILE}" <<'BANNER'
###########################################################
##  AUTO-GENERATED FILE - DO NOT EDIT BY HAND
##
##  Generated by : .github/scripts/generate-docker-compose.sh
##  Sources      : .github/scripts/.upstream/docker-compose.yml  (pruned to SYNC_DIRS)
##                 */compose.override.yml                          (wired into include)
##
##  To customize a service, edit <service>/compose.override.yml
##  (create it if missing) and re-run the script.
###########################################################
BANNER

# 四步：① include 只留 SYNC_DIRS；② 命名卷只留 SYNC_DIRS；
# ③ 有 <service>/compose.override.yml 的条目，把 path 从字符串改写成 [上游, 定制]；
# ④ 每个条目的 env_file 前置 .env.upstream 兜底（原来是字符串就先包成列表）。
#    列表内后者覆盖前者，放最前 = 优先级最低，上游 <service>/defaults.env 说了算。
# （本机 yq 不支持 `if/then/else`，用 `with(select(…); …)` 表达条件更新。）
# $names / $ovr 是 yq 的变量，表达式必须单引号包住
# shellcheck disable=SC2016
NAMES_FILE="${names_file}" OVERRIDES_FILE="${ovr_file}" \
OVERRIDE_BASENAME="${OVERRIDE_BASENAME}" UPSTREAM_ENV_REL="${UPSTREAM_ENV_REL}" yq eval '
  (load(strenv(NAMES_FILE)) // []) as $names |
  (load(strenv(OVERRIDES_FILE)) // []) as $ovr |
  .include |= [.[] | select((.path | split("/") | .[0]) as $d | $names | any_c(. == $d))] |
  .volumes |= with_entries(select(.key as $k | $names | any_c(. == $k))) |
  with(
    .include[] | select((.path | split("/") | .[0]) as $d | $ovr | any_c(. == $d));
    .path |= [., (split("/") | .[0]) + "/" + strenv(OVERRIDE_BASENAME)]
  ) |
  .include[].env_file |= ([strenv(UPSTREAM_ENV_REL)] + ([. // []] | flatten))
' "${SRC_FILE}" >> "${DEST_FILE}"

echo "==> Done. Wrote ${DEST_FILE#"${ROOT_DIR}"/}"
